export type UserRole = 'admin' | 'member' | 'guest';

export interface AuthUser {
  id: string;
  email: string;
  role: UserRole;
  suspended?: boolean;
}

export interface SessionToken {
  token: string;
  userId: string;
  expiresAtMs: number;
}

export interface AuthResult {
  ok: boolean;
  user?: AuthUser;
  reason?: 'missing_token' | 'expired' | 'suspended' | 'forbidden';
}

import { AuthResult, AuthUser, SessionToken, UserRole } from './userTypes';

export interface TokenStore {
  findToken(rawToken: string): SessionToken | undefined;
  findUserById(userId: string): AuthUser | undefined;
}

export class AuthService {
  constructor(
    private readonly store: TokenStore,
    private readonly now: () => number = () => Date.now()
  ) {}
}

  authorize(rawToken: string, requiredRole: UserRole = 'member'): AuthResult {
    if (!rawToken || !rawToken.trim()) {
      return { ok: false, reason: 'missing_token' };
    }

    const session = this.store.findToken(rawToken.trim());
    if (!session || session.expiresAtMs <= this.now()) {
      return { ok: false, reason: 'expired' };
    }

    const user = this.store.findUserById(session.userId);
    if (!user || user.suspended) {
      return { ok: false, reason: 'suspended' };
    }

    const rank: Record<UserRole, number> = { guest: 0, member: 1, admin: 2 };
    if (rank[user.role] < rank[requiredRole]) {
      return { ok: false, reason: 'forbidden' };
    }

    return { ok: true, user };
  }
}
